import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int initialStep = sc.nextInt();

        class StepCounter {
            void increment() {
                // Bug: Modifying local variable inside local inner class
                initialStep++; 
            }
        }

        StepCounter counter = new StepCounter();
        counter.increment();
        System.out.println("Processed Steps: " + initialStep);
    }
}

